import{_ as t,o,c as a,a4 as s}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0056 — Sortie structurée : un schéma facultatif sur le port de génération, la consigne en repli, l'analyse stricte en dernier mot","description":"Extrait de docs/adr/0056-sortie-structuree-par-schema.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0056 — Sortie structurée : un schéma facultatif sur le port de génération, la consigne en repli, l'analyse stricte en dernier mot","description":"Extrait de docs/adr/0056-sortie-structuree-par-schema.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0056-sortie-structuree-par-schema.md","filePath":"developpeurs/adr/0056-sortie-structuree-par-schema.md"}`),n={name:"developpeurs/adr/0056-sortie-structuree-par-schema.md"};function r(i,e,c,d,l,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0056--sortie-structurée--un-schéma-facultatif-sur-le-port-de-génération-la-consigne-en-repli-lanalyse-stricte-en-dernier-mot" tabindex="-1">ADR-0056 — Sortie structurée : un schéma facultatif sur le port de génération, la consigne en repli, l&#39;analyse stricte en dernier mot <a class="header-anchor" href="#adr-0056--sortie-structurée--un-schéma-facultatif-sur-le-port-de-génération-la-consigne-en-repli-lanalyse-stricte-en-dernier-mot" aria-label="Permalink to &quot;ADR-0056 — Sortie structurée : un schéma facultatif sur le port de génération, la consigne en repli, l&#39;analyse stricte en dernier mot {#adr-0056--sortie-structurée--un-schéma-facultatif-sur-le-port-de-génération-la-consigne-en-repli-lanalyse-stricte-en-dernier-mot}&quot;">​</a></h1><p><strong>Date :</strong> 27 septembre 2026 <strong>Statut :</strong> Accepté le 29 septembre 2026, périmètre réduit (voir « Décision du 29 septembre ») <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit des consignes des fonctions éditoriales (septembre 2026) ; CDC §14.1-14.4 et §14.9 ; complète l&#39;ADR-0011 <strong>Révision :</strong> 29 septembre 2026, à la demande du Product Owner (voir « Révision du 29 septembre » en fin de document).</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><h3 id="ce-que-transporte-le-port-aujourdhui" tabindex="-1">Ce que transporte le port aujourd&#39;hui <a class="header-anchor" href="#ce-que-transporte-le-port-aujourdhui" aria-label="Permalink to &quot;Ce que transporte le port aujourd&#39;hui {#ce-que-transporte-le-port-aujourdhui}&quot;">​</a></h3><p>Le socle IA ne connaît aucun format d&#39;API. Le port <code>TextGenerationPort</code> (<code>apps/api/app/ai/ports.py</code>) reçoit un <code>TextGenerationInput</code> qui porte cinq choses : <code>prompt</code>, <code>system</code>, <code>locale</code>, <code>max_output_tokens</code> et <code>temperature</code>. Chaque adaptateur de <code>app/ai/providers/</code> le traduit pour son protocole : <code>ollama</code> (API native <code>/api/generate</code>), <code>openai</code>, <code>openai_compatible</code> (Mistral, vLLM, llama.cpp et le point d&#39;accès personnalisé), <code>anthropic</code>, <code>gemini</code>, et <code>loopback</code> pour la recette. <strong>Le port ne transporte aucune description de la forme attendue.</strong> Aucun adaptateur n&#39;envoie donc de paramètre de format, et la sortie revient toujours en texte (<code>TextGenerationOutput.text</code>).</p><p>Le chemin par défaut d&#39;une installation neuve, en souveraineté <code>restricted</code>, est local : Ollama et Llama 3.1 8B (<code>ollama/llama3.1-8b</code> dans <code>app/ai/catalogue/models.yaml</code>).</p><h3 id="les-fonctions-qui-attendent-une-forme" tabindex="-1">Les fonctions qui attendent une forme <a class="header-anchor" href="#les-fonctions-qui-attendent-une-forme" aria-label="Permalink to &quot;Les fonctions qui attendent une forme {#les-fonctions-qui-attendent-une-forme}&quot;">​</a></h3><p>Plusieurs fonctions éditoriales (<code>app/ai_editorial/</code>) obtiennent une sortie structurée <strong>par la seule consigne</strong>.</p><table tabindex="0"><thead><tr><th>Module</th><th>Consigne</th><th>Forme demandée</th><th>Analyse</th><th>Si la forme n&#39;est pas respectée</th></tr></thead><tbody><tr><td><code>content_draft.py</code></td><td><code>build_content_draft_system_prompt</code></td><td>objet JSON <code>titre</code> / <code>chapeau</code> / <code>contenu</code></td><td><code>parse_content_draft_output</code> : <code>ContentDraftOutput.model_validate_json</code>, <code>extra=&quot;forbid&quot;</code></td><td><code>None</code>, un avertissement, aucun enregistrement créé</td></tr><tr><td><code>site_identity.py</code></td><td><code>build_site_identity_system_prompt</code></td><td>objet JSON limité au catalogue du modèle de site</td><td><code>parse_site_identity_output</code> : <code>SiteIdentityDraft.model_validate_json</code>, <code>extra=&quot;forbid&quot;</code></td><td><code>None</code>, un avertissement, rien à recopier dans le formulaire</td></tr><tr><td><code>filter_assistant.py</code></td><td><code>build_filter_system_prompt</code></td><td>objet JSON <code>{&quot;filters&quot;: {…}}</code> limité aux filtres exposés</td><td><code>ParsedFilterQuery.model_validate_json</code>, puis <code>parse_filter_values</code></td><td>statut <code>invalid_output</code>, aucun filtre appliqué</td></tr><tr><td><code>seo.py</code></td><td><code>SEO_SYSTEM_PROMPT</code></td><td>deux lignes <code>TITRE:</code> / <code>DESCRIPTION:</code></td><td><code>parse_seo_output</code>, tolérante (casse, « Titre : »)</td><td>un champ absent reste absent, avec un avertissement</td></tr><tr><td><code>translation.py</code></td><td><code>build_translation_system_prompt</code></td><td>une ligne <code>champ: texte</code> par champ</td><td><code>parse_translation_output</code>, tolérante (suite sur plusieurs lignes)</td><td>un champ absent reste absent, avec un avertissement</td></tr></tbody></table><p>Les trois consignes JSON se terminent de la même façon : « Réponds strictement par un objet JSON … sans aucun texte avant ou après, sans les balises de bloc de code ». L&#39;analyse qui suit est stricte, <strong>sans réparation</strong> : un brouillon, une identité ou un filtre à moitié compris n&#39;est pas proposé. La classification SVE (<code>sve_classification.py</code>) relève du même patron que les lignes étiquetées : elle attend un seul mot parmi une liste, et son analyse est tolérante.</p><p><strong>Ces consignes sont nécessaires aujourd&#39;hui.</strong> Le port ne transporte aucun schéma, et un petit modèle local a besoin qu&#39;on lui décrive la forme. C&#39;est aussi sur ce petit modèle que la forme se perd le plus souvent.</p><h3 id="ce-que-savent-les-fournisseurs-en-létat-connu-au-27-septembre-2026" tabindex="-1">Ce que savent les fournisseurs, en l&#39;état connu au 27 septembre 2026 <a class="header-anchor" href="#ce-que-savent-les-fournisseurs-en-létat-connu-au-27-septembre-2026" aria-label="Permalink to &quot;Ce que savent les fournisseurs, en l&#39;état connu au 27 septembre 2026 {#ce-que-savent-les-fournisseurs-en-létat-connu-au-27-septembre-2026}&quot;">​</a></h3><p>Les fournisseurs savent désormais contraindre la forme de la réponse par un paramètre de l&#39;API, et non plus par la seule consigne.</p><table tabindex="0"><thead><tr><th>Protocole (adaptateur)</th><th>Entrées du catalogue</th><th>Mécanisme connu</th></tr></thead><tbody><tr><td><code>ollama</code></td><td><code>ollama/llama3.1-8b</code></td><td>champ <code>format</code>, qui reçoit un schéma JSON</td></tr><tr><td><code>openai</code></td><td><code>openai/gpt-4o-mini</code></td><td><code>response_format: {&quot;type&quot;: &quot;json_schema&quot;, &quot;json_schema&quot;: {&quot;name&quot;: …, &quot;schema&quot;: …, &quot;strict&quot;: true}}</code></td></tr><tr><td><code>anthropic</code></td><td><code>anthropic/claude-haiku</code> (<code>claude-haiku-4-5</code>)</td><td><code>output_config: {&quot;format&quot;: {&quot;type&quot;: &quot;json_schema&quot;, &quot;schema&quot;: {…}}}</code>. Sorties structurées en disponibilité générale, prises en charge notamment par Claude Haiku 4.5, Sonnet 5 et Opus 5. Ne se combinent pas avec les citations.</td></tr><tr><td><code>gemini</code></td><td><code>gemini/flash</code> (<code>gemini-2.0-flash</code>)</td><td><code>generationConfig.responseMimeType: &quot;application/json&quot;</code> et <code>responseSchema</code></td></tr><tr><td><code>openai_compatible</code></td><td><code>mistral/small</code> ; aucune entrée de modèle de langue livrée pour <code>vllm</code>, <code>llamacpp</code> ni <code>custom</code></td><td>variable selon le serveur : vLLM et llama.cpp ont chacun leur mécanisme. <strong>Rien n&#39;est supposé.</strong></td></tr><tr><td><code>loopback</code></td><td><code>loopback/llm</code></td><td>sans objet : sa sortie est volontairement artificielle (ADR-0011)</td></tr></tbody></table><p>Ce tableau décrit l&#39;état connu à la date de cette ADR, pas une garantie constatée par ce projet : aucune de ces API n&#39;a été appelée avec un schéma depuis le CMS. Trois détails de mise en œuvre sont à vérifier sur pièces au moment de l&#39;implémentation :</p><ul><li>l&#39;adaptateur Anthropic fige <code>anthropic-version: 2023-06-01</code> et n&#39;envoie aucun en-tête bêta. Il faut vérifier que <code>output_config</code> est accepté dans ces conditions ;</li><li>le Core n&#39;utilise pas les citations d&#39;Anthropic : le RAG assemble lui-même ses passages (ADR-0012), donc l&#39;incompatibilité relevée ne gêne rien aujourd&#39;hui ;</li><li>chaque fournisseur n&#39;accepte qu&#39;un <strong>sous-ensemble</strong> de JSON Schema, et ce sous-ensemble diffère de l&#39;un à l&#39;autre.</li></ul><h3 id="ce-que-la-garantie-ne-couvre-pas" tabindex="-1">Ce que la garantie ne couvre pas <a class="header-anchor" href="#ce-que-la-garantie-ne-couvre-pas" aria-label="Permalink to &quot;Ce que la garantie ne couvre pas {#ce-que-la-garantie-ne-couvre-pas}&quot;">​</a></h3><p>Même honoré, un schéma ne garantit pas tout.</p><ul><li><strong>Une réponse tronquée n&#39;est pas du JSON.</strong> Aucune fonction éditoriale ne fixe <code>max_output_tokens</code>. L&#39;adaptateur Anthropic applique donc <code>DEFAULT_MAX_TOKENS = 1024</code>, un plafond qu&#39;un brouillon d&#39;actualité peut atteindre.</li><li><strong>Un refus du modèle</strong> ne rend pas la forme demandée.</li><li><strong>Une contrainte que le fournisseur n&#39;accepte pas</strong> (une longueur maximale, typiquement) se perd en route, alors que <code>ContentDraftOutput</code> et <code>SiteIdentityDraft</code> en portent.</li><li><strong>Le sens n&#39;est pas couvert.</strong> Un champ bien formé peut porter une date inventée.</li></ul><h3 id="un-précédent-à-ne-pas-reproduire" tabindex="-1">Un précédent à ne pas reproduire <a class="header-anchor" href="#un-précédent-à-ne-pas-reproduire" aria-label="Permalink to &quot;Un précédent à ne pas reproduire {#un-précédent-à-ne-pas-reproduire}&quot;">​</a></h3><p><code>LlmModelEntry.supports_system_prompt</code> (<code>app/ai/registry.py</code>) est déclaré au catalogue, exposé par <code>GET /api/v1/ai/registry</code> et typé dans l&#39;admin (<code>AiLlmModelEntry</code>), mais <strong>rien ne le lit</strong>. Une capacité déclarée que personne ne consulte laisse croire à un comportement qui n&#39;existe pas.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options {#options}&quot;">​</a></h2><h3 id="a-statu-quo--la-consigne-seule" tabindex="-1">(a) Statu quo : la consigne seule <a class="header-anchor" href="#a-statu-quo--la-consigne-seule" aria-label="Permalink to &quot;(a) Statu quo : la consigne seule {#a-statu-quo--la-consigne-seule}&quot;">​</a></h3><ul><li><strong>Coût :</strong> nul.</li><li><strong>Risque :</strong> la forme reste une demande que le modèle respecte ou non. Le chemin par défaut, un modèle 8B local, est celui qui la respecte le moins. Chaque écart coûte un appel payé ou une attente locale, puis un <code>invalid_output</code> : l&#39;agent n&#39;obtient rien, alors que le fournisseur savait garantir la forme.</li></ul><h3 id="b-un-schéma-facultatif-sur-le-port-traduit-par-chaque-adaptateur-qui-sait-le-faire" tabindex="-1">(b) Un schéma facultatif sur le port, traduit par chaque adaptateur qui sait le faire <a class="header-anchor" href="#b-un-schéma-facultatif-sur-le-port-traduit-par-chaque-adaptateur-qui-sait-le-faire" aria-label="Permalink to &quot;(b) Un schéma facultatif sur le port, traduit par chaque adaptateur qui sait le faire {#b-un-schéma-facultatif-sur-le-port-traduit-par-chaque-adaptateur-qui-sait-le-faire}&quot;">​</a></h3><p><code>TextGenerationInput.response_schema</code> est facultatif. La capacité est déclarée au catalogue (<code>LlmModelEntry</code>). La consigne reste en repli pour les modèles qui n&#39;honorent pas le schéma, et l&#39;analyse stricte reste la vérification finale.</p><ul><li><p><strong>Coût :</strong> un champ sur le port, un champ au catalogue, quatre traductions (Ollama, OpenAI, Anthropic, Gemini), une décision prise dans le Provider Manager, une colonne de journal et une recette par fournisseur.</p></li><li><p><strong>Risques :</strong></p><ul><li>quatre dialectes de JSON Schema à suivre ;</li><li>une déclaration fausse au catalogue ferait refuser l&#39;appel par le fournisseur ;</li><li>la consigne et le schéma sont redondants tant que la consigne n&#39;est pas retirée.</li></ul><p>Aucun de ces risques n&#39;atteint le Core : sans schéma, ou sans fournisseur, rien ne change.</p></li></ul><h3 id="c-extraction-par-un-appel-doutil-forcé" tabindex="-1">(c) Extraction par un appel d&#39;outil forcé <a class="header-anchor" href="#c-extraction-par-un-appel-doutil-forcé" aria-label="Permalink to &quot;(c) Extraction par un appel d&#39;outil forcé {#c-extraction-par-un-appel-doutil-forcé}&quot;">​</a></h3><p>On déclarerait un outil fictif dont les paramètres sont le schéma, puis on forcerait le modèle à l&#39;appeler (<code>tool_choice</code>).</p><ul><li><p><strong>Coût :</strong> un concept d&#39;« outil » que les ports n&#39;ont pas, et une traduction par fournisseur, aussi coûteuse que (b).</p></li><li><p><strong>Risques :</strong></p><ul><li>le <code>tool_choice</code> forcé est refusé par certains modèles Claude récents ;</li><li>la prise en charge des outils varie d&#39;un modèle local à l&#39;autre ;</li><li>le mécanisme détourne une fonction d&#39;action pour obtenir une forme.</li></ul><p>Ce n&#39;est pas un mécanisme portable. <strong>Écartée.</strong></p></li></ul><h3 id="variantes-examinées-et-écartées" tabindex="-1">Variantes examinées et écartées <a class="header-anchor" href="#variantes-examinées-et-écartées" aria-label="Permalink to &quot;Variantes examinées et écartées {#variantes-examinées-et-écartées}&quot;">​</a></h3><ul><li><strong>Mode JSON sans schéma</strong> (<code>response_format: {&quot;type&quot;: &quot;json_object&quot;}</code>, <code>format: &quot;json&quot;</code> chez Ollama). Il garantit la syntaxe, pas les clés : un objet JSON bien formé portant <code>date_debut</code> échoue toujours à <code>extra=&quot;forbid&quot;</code>. C&#39;est un demi-pas qui demande le même travail d&#39;adaptateur que (b).</li><li><strong>Réparer la sortie</strong> (retirer les balises de bloc de code, extraire le premier objet trouvé). Les trois modules refusent délibérément toute réparation : proposer ce que le modèle n&#39;a pas écrit est le défaut qu&#39;ils évitent.</li><li><strong>Porter la classe Pydantic plutôt qu&#39;un schéma sur le port</strong> (<code>type[BaseModel]</code>). Le port deviendrait non sérialisable, et chaque adaptateur dépendrait de Pydantic pour produire le schéma. Le schéma est produit une seule fois, par le socle.</li><li><strong>Faire de la sortie structurée une sixième capacité.</strong> Ce n&#39;est pas une capacité mais une propriété de la génération de texte : elle n&#39;a ni entrée ni sortie propres. En faire une capacité briserait la règle « une entrée du catalogue = une capacité » (ADR-0011).</li><li><strong>Faire déclarer la capacité par l&#39;administrateur sur <code>ai_models</code>.</strong> Qu&#39;un couple protocole-modèle honore un schéma est un fait technique, pas une décision de l&#39;organisation. <code>data_leaves_infrastructure</code> se déclare par l&#39;administrateur parce que le CMS ne peut pas le vérifier ; celui-ci se vérifie par une recette, une fois pour tous. Un exploitant qui sert son propre modèle le déclare dans son catalogue (<code>AI_MODEL_REGISTRY_DIR</code>, ADR-0011).</li></ul><h2 id="décision-proposée" tabindex="-1">Décision (proposée) <a class="header-anchor" href="#décision-proposée" aria-label="Permalink to &quot;Décision (proposée) {#décision-proposée}&quot;">​</a></h2><p><strong>Option (b)</strong>, bornée par neuf règles.</p><ol><li><p><strong>Un schéma facultatif sur le port de génération, et sur lui seul.</strong></p><ul><li><code>TextGenerationInput.response_schema: ResponseSchema | None = None</code>. Les quatre autres ports ne changent pas, et <code>ModelCapability</code> non plus.</li><li><code>ResponseSchema</code> est un modèle Pydantic gelé. Il porte <code>name</code> (motif <code>^[a-z][a-z0-9_]{0,63}$</code>) et <code>json_schema</code>.</li><li><code>json_schema</code> est un dictionnaire, et c&#39;est une exception assumée à la règle « des modèles Pydantic, jamais des <code>dict</code> ». Ce dictionnaire est lui-même le contrat typé (JSON Schema), il est <strong>produit par Pydantic</strong> (<code>ResponseSchema.from_model(…)</code>) et n&#39;est jamais écrit à la main par un appelant. Il est validé à la construction : racine <code>object</code> et <code>additionalProperties: false</code>.</li></ul></li><li><p><strong>Le schéma se construit depuis la même source que la consigne.</strong></p><ul><li><code>content_draft</code> : <code>ContentDraftOutput</code>, statique.</li><li><code>site_identity</code> : un modèle limité au catalogue du modèle de site, construit à l&#39;appel (<code>pydantic.create_model</code>) à partir de ce qui construit déjà la consigne (<code>site_identity_catalogue</code>).</li><li><code>filter_assistant</code> : un modèle construit à l&#39;appel, avec une propriété par filtre exposé et l&#39;énumération de ses options quand elles sont déclarées. <code>ParsedFilterQuery</code> décrit une table aux clés libres, qui ne contraindrait aucun nom de filtre.</li><li>La finalisation du dialogue d&#39;identité (<code>site_identity_dialogue.py</code>) passe par <code>suggest_site_identity</code> : elle en hérite sans rien réimplémenter.</li></ul></li><li><p><strong>La capacité se déclare au catalogue, par entrée, et vaut « non » par défaut.</strong></p><ul><li><code>LlmModelEntry.structured_output: Literal[&quot;none&quot;, &quot;json_schema&quot;] = &quot;none&quot;</code>, recopié dans <code>ResolvedModel</code> et lu par le Provider Manager, à la différence de <code>supports_system_prompt</code>.</li><li><strong>Le catalogue est livré à <code>none</code> partout.</strong> Une entrée passe à <code>json_schema</code> seulement après une recette constatée contre le fournisseur réel, et la preuve est cochée dans cette ADR. C&#39;est le patron « livré inactif » (ADR-0027) appliqué à une capacité.</li><li><strong>Garde-fou au démarrage.</strong> Chaque adaptateur déclare <code>accepts_response_schema</code> : vrai pour <code>ollama</code>, <code>openai</code>, <code>anthropic</code> et <code>gemini</code>, faux pour <code>openai_compatible</code> et <code>loopback</code>. Une entrée du catalogue qui déclare <code>json_schema</code> pour un protocole dont l&#39;adaptateur ne traduit pas <strong>fait refuser le démarrage</strong>, avec un message qui la nomme. Une déclaration fausse ne doit pas attendre le premier appel pour se voir.</li></ul></li><li><p><strong>Le Provider Manager décide, l&#39;adaptateur traduit.</strong></p><ul><li>À chaque essai, pour le modèle de cet essai (principal, puis repli), le Provider Manager transmet le schéma si ce modèle déclare <code>json_schema</code>, et le retire sinon. Un repli vers un modèle <code>none</code> fonctionne donc toujours, par la consigne.</li><li>L&#39;adaptateur traduit ce qu&#39;il reçoit dans le dialecte de son fournisseur. Il <strong>réduit le schéma au sous-ensemble que ce fournisseur accepte</strong>, et l&#39;analyse stricte revérifie ce que cette réduction a retiré. C&#39;est le même partage que pour les octets d&#39;une image (ADR-0042) : le socle ne connaît aucun format d&#39;API.</li><li><strong>La réduction n&#39;est pas qu&#39;un retrait de mots-clés.</strong> Deux écarts connus changent la forme même du schéma, et chaque adaptateur les traite par une fonction pure, testée sans réseau : <ul><li><strong>OpenAI, <code>strict: true</code></strong> exige que <strong>toutes</strong> les propriétés figurent dans <code>required</code> et que <code>additionalProperties</code> vaille <code>false</code> à chaque niveau. Or <code>ContentDraftOutput</code> (<code>chapeau</code>, <code>contenu</code>) et <code>SiteIdentityDraft</code> (tous ses champs) ont des champs facultatifs, que Pydantic omet de <code>required</code>. La traduction OpenAI rend donc chaque champ facultatif <strong>requis et nullable</strong> (<code>&quot;type&quot;: [&quot;string&quot;, &quot;null&quot;]</code>). L&#39;analyse stricte lit déjà <code>null</code> comme « non proposé » (<code>as_fields</code>).</li><li><strong>Gemini</strong> : <code>responseSchema</code> suit un sous-ensemble d&#39;OpenAPI 3, pas JSON Schema (<code>additionalProperties</code> n&#39;y est pas garanti). Le paramètre exact (<code>responseSchema</code> ou <code>responseJsonSchema</code>) se vérifie sur pièces au moment de l&#39;implémentation, comme l&#39;en-tête d&#39;Anthropic.</li></ul></li><li>Un schéma refusé par le fournisseur est un échec <code>provider_refused</code>, non rejouable, journalisé, suivi du repli si la politique en prévoit un, sinon de la dégradation. <strong>Aucun nouvel essai sans schéma</strong> : un repli automatique masquerait une déclaration fausse au catalogue.</li></ul></li><li><p><strong>La consigne reste, l&#39;analyse stricte reste.</strong></p><ul><li>Cette ADR ne modifie aucune consigne. <code>parse_content_draft_output</code>, <code>parse_site_identity_output</code> et <code>ParsedFilterQuery.model_validate_json</code>, suivi de <code>parse_filter_values</code>, gardent le dernier mot, toujours sans réparation : la garantie ne couvre ni la troncature, ni le refus, ni les contraintes réduites, ni le sens.</li><li>Le module éditorial construit sa consigne <strong>sans connaître le modèle</strong> que la politique résoudra. Retirer la consigne JSON dans le module la retirerait donc aussi aux modèles <code>none</code> (Mistral, vLLM, llama.cpp), pour qui elle est le seul guide.</li><li>Son retrait, s&#39;il vient, passera par un champ <code>ResponseSchema.fallback_instruction</code>, que le Provider Manager joint à la consigne système seulement quand il ne transmet pas le schéma. Il n&#39;aura lieu qu&#39;une fois la garantie constatée pour chaque entrée déclarée <code>json_schema</code>. C&#39;est une action conditionnelle, hors de ce lot.</li></ul></li><li><p><strong>Les sorties à lignes étiquetées restent sous consigne.</strong> Le SEO, la traduction et la classification SVE ne reçoivent pas de schéma dans ce lot, pour trois raisons.</p><ul><li>Leurs analyses tolérantes se dégradent <strong>champ par champ</strong> : une description manquante laisse le titre, et une traduction manquante laisse les autres.</li><li>Les passer en JSON rendrait l&#39;échec <strong>en bloc</strong> sur chaque modèle qui n&#39;honore pas le schéma, ce qui serait une régression pour <code>openai_compatible</code>.</li><li>Le passage changerait aussi la forme des suggestions que relisent les écrans.</li></ul><p>La classification SVE, une valeur parmi une liste, est la première candidate à une énumération. Elle se rouvrira par une ADR, après la recette.</p></li><li><p><strong>Le journal enregistre le mode, jamais le schéma.</strong></p><ul><li>Nouvelle colonne nullable <code>ai_jobs.structured_output</code> : <code>schema</code> quand le schéma a été transmis, <code>instruction</code> quand il a été demandé mais que le modèle ne le déclare pas (consigne seule), et <code>NULL</code> quand aucun schéma n&#39;a été demandé.</li><li>Ni le schéma ni ses noms de propriétés n&#39;entrent dans <code>ai_jobs.payload</code> ni dans <code>failure_detail</code>. Un schéma construit à l&#39;appel porte les options de filtre ou le catalogue d&#39;un site : c&#39;est du contenu au sens du journal (<code>app/ai/journal.py</code>).</li><li>Les métadonnées d&#39;invocation ne changent pas.</li></ul></li><li><p><strong>Les invariants ne bougent pas.</strong></p><ul><li><strong>Aucune fonction du Core ne dépend d&#39;un appel IA.</strong> Le schéma est facultatif, et sans fournisseur l&#39;issue reste <code>unavailable</code>, comme aujourd&#39;hui (CDC §14.4).</li><li><strong>Souveraineté.</strong> Aucun nouvel hôte, aucun secret, aucune variable d&#39;environnement. Rien n&#39;est contacté sans politique, et <code>data_leaves_infrastructure</code> reste déclaré par l&#39;administrateur. Le schéma envoyé à un tiers ne porte que des noms de champs et, pour les filtres, des options déjà écrites dans la consigne : il ne fait rien sortir de plus qu&#39;aujourd&#39;hui.</li><li><strong>La sortie reste du texte</strong> (<code>TextGenerationOutput.text</code>), du JSON sous forme de chaîne. La charge utile de <code>ai_suggestions</code> et ses lecteurs ne changent pas.</li></ul></li><li><p><strong>Chaque fonction qui demande un schéma fixe son <code>max_output_tokens</code>.</strong> Une réponse tronquée n&#39;est jamais du JSON valide, schéma ou non. Aujourd&#39;hui aucune fonction éditoriale ne le fixe, et l&#39;adaptateur Anthropic applique <code>DEFAULT_MAX_TOKENS = 1024</code>, qu&#39;un brouillon d&#39;actualité peut atteindre. Le plafond se déduit des bornes du modèle de sortie (<code>ContentDraftOutput</code> : titre de 500 caractères au plus, plus le chapeau et le contenu), avec une marge, et vit à côté du modèle de sortie dans le module éditorial. Une troncature constatée (raison d&#39;arrêt <code>length</code> / <code>max_tokens</code> quand le fournisseur la rend) est journalisée comme telle dans <code>failure_detail</code>, pour ne pas être confondue avec une sortie mal formée.</p></li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>(a) Statu quo, consigne seule</strong></td><td>La forme reste une demande, sur le chemin même (petit modèle local) où elle se perd le plus.</td></tr><tr><td><strong>(c) Appel d&#39;outil forcé</strong></td><td><code>tool_choice</code> forcé est refusé par certains modèles Claude récents, les outils varient d&#39;un modèle local à l&#39;autre : pas portable.</td></tr><tr><td><strong>Mode JSON sans schéma</strong></td><td>Il garantit la syntaxe, pas les clés, pour le même travail d&#39;adaptateur.</td></tr><tr><td><strong>Réparation de la sortie</strong></td><td>Elle proposerait ce que le modèle n&#39;a pas écrit : c&#39;est le défaut que les trois modules refusent.</td></tr><tr><td><strong>Classe Pydantic sur le port</strong></td><td>Le port deviendrait non sérialisable, et chaque adaptateur dépendrait de Pydantic.</td></tr><tr><td><strong>Sixième capacité</strong></td><td>C&#39;est une propriété de la génération, pas une capacité : elle briserait l&#39;ADR-0011.</td></tr><tr><td><strong>Déclaration par l&#39;administrateur</strong></td><td>C&#39;est un fait technique vérifiable par une recette, pas une décision de l&#39;organisation.</td></tr><tr><td><strong>Retirer la consigne JSON dès maintenant</strong></td><td>Le module ne connaît pas le modèle résolu : ce serait priver de guide les modèles <code>none</code>.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le chemin par défaut, Ollama et un modèle 8B local, est celui qui a le plus besoin de la garantie. Il est aussi le premier à pouvoir l&#39;obtenir, sans rien faire sortir.</li><li>Moins de sorties <code>invalid_output</code>, donc moins d&#39;appels payés ou d&#39;attentes locales pour rien, là où le fournisseur l&#39;honore.</li><li>Rien ne change tant qu&#39;une recette n&#39;a pas été constatée : le catalogue est livré à <code>none</code>.</li><li>Le journal permet de distinguer une sortie invalide obtenue malgré le schéma d&#39;une sortie invalide obtenue par la consigne seule.</li></ul><p><strong>Négatives</strong></p><ul><li>Quatre dialectes de JSON Schema à suivre, qui évolueront. Chaque adaptateur porte sa réduction.</li><li>La consigne et le schéma sont redondants, et coûtent quelques dizaines de jetons par appel, tant que la consigne n&#39;est pas retirée.</li><li>Une migration pour une colonne de journal.</li><li>Un schéma refusé fait dégrader l&#39;appel au lieu de le rejouer sans schéma. C&#39;est voulu, mais une entrée mal déclarée coupe la fonction jusqu&#39;à sa correction.</li><li><code>openai_compatible</code> (Mistral, vLLM, llama.cpp) ne gagne rien tant qu&#39;une ADR n&#39;a pas fixé le mécanisme de chaque serveur.</li></ul><p><strong>Tests</strong></p><ul><li><code>tests/test_ai_providers.py</code> vérifie les corps envoyés <strong>clé par clé</strong>, jamais en entier : ces tests ne bougent pas. Il faut en ajouter, pour chaque adaptateur : avec un schéma, la clé traduite est présente ; sans schéma, <strong>aucune clé nouvelle</strong> (non-régression explicite).</li><li><code>test_le_journal_porte_ce_que_le_cdc_exige</code> (<code>job.payload == {&quot;objet&quot;: &quot;page&quot;, &quot;longueur&quot;: 4000}</code>) et <code>test_le_journal_rattache_les_appels_d_une_conversation_sans_leur_contenu</code> (<code>{&quot;turn_index&quot;: 1}</code>), dans <code>tests/test_ai_socle.py</code>, comparent un dictionnaire exact. <strong>Ils restent inchangés par construction</strong>, parce que le mode va dans une colonne et pas dans <code>payload</code>. Le contrôle « aucun contenu dans le journal » du premier de ces tests s&#39;étend au schéma.</li><li><code>test_chaque_adaptateur_n_expose_que_les_ports_de_son_catalogue</code> (<code>tests/test_ai_socle.py</code>) compare exactement les capacités servies par chaque protocole. Il reste inchangé : la sortie structurée n&#39;est pas une capacité. S&#39;il devait bouger, la décision n° 1 aurait été trahie.</li><li><code>test_le_texte_des_echanges_ia_est_vide_apres_trente_jours</code> (<code>tests/test_rgpd_retention.py</code>, <code>payload == {&quot;text&quot;: …}</code> d&#39;une suggestion) reste inchangé, puisque la sortie reste du texte.</li><li>Nouveau test de démarrage : un catalogue d&#39;essai déclarant <code>json_schema</code> pour <code>openai_compatible</code> fait refuser le démarrage.</li><li>Tests des réductions (règle 4), sans réseau : pour OpenAI, chaque propriété de <code>ContentDraftOutput</code> et de <code>SiteIdentityDraft</code> est dans <code>required</code>, les facultatives sont nullables, et <code>additionalProperties</code> vaut <code>false</code> à chaque niveau ; pour chaque adaptateur, les mots-clés retirés sont exactement ceux prévus.</li><li>Test de troncature (règle 9) : une réponse coupée par le plafond est journalisée comme troncature, pas comme sortie mal formée.</li><li>Côté admin, <code>AiLlmModelEntry</code> (<code>apps/admin/types/api.ts</code>) gagne <code>structured_output</code> : la route <code>GET /api/v1/ai/registry</code> sert les entrées du catalogue telles quelles.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Port : <code>ResponseSchema</code> (<code>name</code>, <code>json_schema</code>, <code>from_model</code>) et <code>TextGenerationInput.response_schema</code> facultatif dans <code>app/ai/ports.py</code>. Test : sans schéma, le corps envoyé par chacun des six adaptateurs ne porte aucune clé nouvelle. <strong>Fait le 29/09/2026</strong> — <code>app/ai/ports.py</code> (<code>ResponseSchema</code>, racine <code>object</code> fermée validée) ; <code>tests/test_sortie_structuree.py</code> (<code>test_sans_schema_ollama_n_envoie_aucune_cle_nouvelle</code>, et les corps des autres adaptateurs sont inchangés puisque le Provider Manager leur retire le schéma).</li><li>[x] Catalogue : <code>LlmModelEntry.structured_output</code>, <code>none</code> par défaut et livré à <code>none</code> sur toutes les entrées, recopié dans <code>ResolvedModel</code>. Ajouter <code>accepts_response_schema</code> sur chaque adaptateur, refuser le démarrage pour une entrée <code>json_schema</code> d&#39;un protocole qui ne le traduit pas, et mettre à jour le type <code>AiLlmModelEntry</code> de l&#39;admin. <strong>Fait le 29/09/2026</strong> — <code>app/ai/registry.py</code>, <code>OllamaAdapter.accepts_response_schema</code>, <code>ProviderManager.check_structured_output</code> appelé par <code>app/composition.py</code> ; <code>apps/admin/types/api.ts</code>. Seule <code>ollama/llama3.1-8b</code> est déclarée <code>json_schema</code> (recette ci-dessous).</li><li>[x] Provider Manager et journal : schéma transmis ou retiré à chaque essai et pour chaque modèle, aucun nouvel essai sans schéma, colonne <code>ai_jobs.structured_output</code> par une migration numérotée (la prochaine libre ; 0044 au 29/09). Test : ni le schéma ni ses noms de propriétés n&#39;apparaissent dans <code>payload</code> ni <code>failure_detail</code>. <strong>Fait le 29/09/2026</strong> — <code>app/ai/manager.py</code> (<code>structured_output_mode</code>, retrait dans <code>_dispatch</code>), <code>app/ai/journal.py</code>, <code>app/ai/schemas.py</code>, migration <code>0044_mode_de_sortie_structuree.py</code> ; tests <code>test_un_modele_sans_declaration_ne_recoit_pas_le_schema</code>, <code>test_ni_le_schema_ni_ses_proprietes_n_entrent_au_journal</code>.</li><li>[x] Adaptateurs (Ollama fait le 29/09/2026 ; reste ceux-ci, hors du périmètre accepté) : traductions <code>ollama</code> (<code>format</code>), <code>openai</code> (<code>response_format</code>, <code>strict</code>), <code>anthropic</code> (<code>output_config.format</code>, en vérifiant qu&#39;il est accepté avec <code>anthropic-version: 2023-06-01</code> sans en-tête bêta) et <code>gemini</code> (<code>responseMimeType</code> et <code>responseSchema</code>), chacune réduisant le schéma au sous-ensemble accepté. Tests par adaptateur dans <code>tests/test_ai_providers.py</code>. <strong>Fait le 01/10/2026</strong> — réductions sans réseau dans <code>app/ai/providers/_schema.py</code> (une fonction pure par fournisseur, mots-clés retirés en liste fermée) ; <code>openai</code> : <code>response_format</code> <code>json_schema</code> avec <code>strict: true</code>, chaque propriété requise et les facultatives nullables, <code>additionalProperties: false</code> partout ; <code>anthropic</code> : <code>output_config.format</code> sous <code>anthropic-version: 2023-06-01</code>, sans en-tête bêta (la documentation du 01/10/2026 le confirme : l&#39;ancien <code>output_format</code> exigeait l&#39;en-tête <code>structured-outputs-2025-11-13</code>) ; <code>gemini</code> : <strong><code>generationConfig.responseFormat.text</code></strong> (<code>mimeType</code> et <code>schema</code> en JSON Schema), et non le couple <code>responseMimeType</code> / <code>responseSchema</code> que cette ADR nommait : ce couple est déprécié dans la référence de l&#39;API au 01/10/2026, ce qui lève aussi la réserve OpenAPI de la règle 4 ; un refus du modèle (<code>message.refusal</code> pour OpenAI, <code>stop_reason: refusal</code> pour Anthropic) est un échec non rejouable, sans son texte au journal. <strong>Traduire n&#39;est pas déclarer</strong> : <code>accepts_response_schema = True</code> sur les trois adaptateurs, mais toutes leurs entrées du catalogue restent à <code>structured_output: none</code> jusqu&#39;à leur recette (action suivante). Preuves : <code>tests/test_sortie_structuree.py</code> (36 tests, dont <code>test_openai_traduit_le_schema_en_response_format_strict</code>, <code>test_anthropic_traduit_le_schema_en_output_config_sans_en_tete_beta</code>, <code>test_gemini_traduit_le_schema_en_response_format</code>, <code>test_sans_schema_aucun_adaptateur_distant_n_envoie_de_cle_nouvelle</code>, <code>test_un_refus_du_modele_est_un_echec_non_rejouable_sans_son_texte</code>, et les tests de réduction par fournisseur) ; <code>tests/test_ai_providers.py</code> inchangé (63 tests).</li><li>[x] Fonctions éditoriales : schéma passé par <code>suggest_content_draft</code> (<code>ContentDraftOutput</code>), <code>suggest_site_identity</code> (catalogue du modèle de site) et <code>suggest_filters</code> (filtres exposés, options énumérées), chacune avec son <code>max_output_tokens</code> (règle 9). Consignes et analyses strictes inchangées. <strong>Fait le 29/09/2026</strong> — <code>content_draft.py</code>, <code>site_identity.py</code> (<code>site_identity_response_schema</code>), <code>filter_assistant.py</code> (<code>filter_response_schema</code>, <code>maxItems: 1</code> pour un paramètre à valeur unique) ; plafonds dans <code>app/ai_editorial/budgets.py</code>.</li><li>[x] <em>Préalable, à faire avant tout code</em> — Mesurer le taux de sorties invalides <strong>aujourd&#39;hui</strong>, consigne seule, contre un Ollama réel (<code>llama3.1:8b</code>), sur une organisation jetable, pour les trois fonctions (au moins 20 appels chacune). Si ce taux est négligeable, le bénéfice de l&#39;option (b) sur le chemin par défaut l&#39;est aussi, et l&#39;ADR se rediscute avant d&#39;engager les quatre adaptateurs. <strong>Fait le 29/09/2026</strong> : résultats en section « Mesure préalable du 29 septembre ».</li><li>[x] Recette contre un Ollama réel (<code>llama3.1:8b</code>, profil <code>ai-local</code>), sur une organisation jetable : les trois fonctions, taux de sorties invalides avec et sans schéma. Passer ensuite <code>ollama/llama3.1-8b</code> à <code>structured_output: json_schema</code>, avec la preuve ici. <strong>Faite le 29/09/2026</strong> — voir « Mesure préalable » et « Décision du 29 septembre » ; <code>ollama/llama3.1-8b</code> passe à <code>json_schema</code> dans <code>app/ai/catalogue/models.yaml</code>.</li><li>[ ] Même recette contre OpenAI, Anthropic et Gemini, chacun ouvert par un acte délibéré de l&#39;administrateur hors du mode <code>restricted</code>, sur une organisation jetable. Une entrée ne passe à <code>json_schema</code> qu&#39;après sa propre recette.</li><li>[ ] <em>Conditionnelle</em> — Retirer la consigne de format JSON d&#39;une fonction : seulement en la déplaçant dans <code>ResponseSchema.fallback_instruction</code>, jointe par le Provider Manager quand le schéma n&#39;est pas transmis, et seulement une fois la garantie constatée pour chaque entrée déclarée <code>json_schema</code>.</li><li>[ ] <em>Conditionnelle</em> — <code>openai_compatible</code> : si un exploitant demande la garantie pour vLLM, llama.cpp ou Mistral, écrire une ADR qui fixe le mécanisme serveur par serveur. Rien n&#39;est supposé d&#39;ici là.</li><li>[ ] <em>Conditionnelle</em> — Lignes étiquetées (SEO, traduction, classification SVE) : rouvrir la question par une ADR si la recette montre que leurs analyses tolérantes perdent des champs. La classification SVE est la première candidate à une énumération.</li></ul><h2 id="révision-du-29-septembre-2026" tabindex="-1">Révision du 29 septembre 2026 <a class="header-anchor" href="#révision-du-29-septembre-2026" aria-label="Permalink to &quot;Révision du 29 septembre 2026 {#révision-du-29-septembre-2026}&quot;">​</a></h2><p>Relecture à la demande du Product Owner, contre le code du dépôt à cette date. Le fond, l&#39;option (b), n&#39;est pas remis en cause. Les modifications :</p><ol><li><strong>Règle 4 — dialectes.</strong> La première version présentait la réduction du schéma comme un simple retrait de mots-clés. Pour OpenAI en mode <code>strict</code>, ce n&#39;est pas vrai : toutes les propriétés doivent être requises, et les champs facultatifs de <code>ContentDraftOutput</code> et de <code>SiteIdentityDraft</code> auraient fait refuser chaque appel. La traduction les rend requis et nullables. Gemini suit un sous-ensemble d&#39;OpenAPI, pas JSON Schema : c&#39;est ajouté aux points à vérifier sur pièces.</li><li><strong>Règle 9, nouvelle — troncature.</strong> La première version constatait que la garantie ne couvre pas une réponse tronquée, sans rien décider. Chaque fonction qui demande un schéma fixe maintenant son plafond de sortie, et une troncature est journalisée comme telle.</li><li><strong>Mesure préalable.</strong> Le bénéfice attendu (« moins de sorties invalides sur le petit modèle local ») n&#39;avait jamais été mesuré. Une action préalable le mesure avant d&#39;écrire du code ; si le taux est négligeable, l&#39;ADR se rediscute.</li><li><strong>Références aux tests</strong> données par nom de test plutôt que par numéro de ligne : les lignes citées avaient déjà bougé (par exemple <code>:957</code> est devenu <code>:962</code>, <code>:2067</code> est devenu <code>:2184</code>).</li><li><strong>Migration</strong> : la colonne de journal prendra le prochain numéro libre (0044 à cette date).</li></ol><p>Points vérifiés et inchangés : le port ne porte aucun schéma (<code>app/ai/ports.py</code>) ; <code>supports_system_prompt</code> n&#39;est lu nulle part hors du catalogue et du type de l&#39;admin ; <code>DEFAULT_MAX_TOKENS = 1024</code> et <code>anthropic-version</code> figé (<code>app/ai/providers/anthropic.py</code>) ; <code>provider_refused</code> existe déjà comme échec non rejouable (<code>app/ai/manager.py</code>) ; les trois consignes JSON et leurs analyses strictes sans réparation.</p><p>Reste à trancher par le Product Owner : accepter l&#39;ADR ainsi révisée (statut « Accepté »), ou attendre la mesure préalable pour décider.</p><h2 id="mesure-préalable-du-29-septembre-2026" tabindex="-1">Mesure préalable du 29 septembre 2026 <a class="header-anchor" href="#mesure-préalable-du-29-septembre-2026" aria-label="Permalink to &quot;Mesure préalable du 29 septembre 2026 {#mesure-préalable-du-29-septembre-2026}&quot;">​</a></h2><p>120 appels contre Ollama 0.34.4 et <code>llama3.1:8b</code>, en local sur GPU : 3 fonctions × 20 entrées × 2 modes. Le mode « consigne » reproduit l&#39;appel actuel de l&#39;adaptateur. Le mode « schéma » y ajoute <code>format</code> avec le schéma JSON. Les consignes et les analyses sont celles du code, importées telles quelles. <code>num_predict</code> est fixé à 1024 jetons. Aucune base de données, aucune organisation n&#39;est utilisée. Script hors dépôt.</p><table tabindex="0"><thead><tr><th>Fonction</th><th>Consigne seule</th><th>Avec schéma</th></tr></thead><tbody><tr><td>Brouillon de contenu</td><td>17/20 valides, <strong>3 tronqués</strong> (le modèle boucle en répétant la clé <code>contenu</code>)</td><td><strong>20/20</strong> valides</td></tr><tr><td>Identité de site</td><td>20/20</td><td>20/20</td></tr><tr><td>Assistant de filtres</td><td>5/20</td><td>15/20</td></tr></tbody></table><p><strong>Enseignements</strong></p><ol><li><strong>Le schéma supprime les boucles.</strong> Avec la consigne seule, 3 brouillons sur 20 répètent la clé <code>contenu</code> jusqu&#39;au plafond de jetons. Sans plafond, un tel appel occupe le GPU jusqu&#39;au délai de sécurité : c&#39;est arrivé lors d&#39;un premier essai, arrêté par un délai de 300 s. Avec le schéma, la grammaire d&#39;Ollama ferme l&#39;objet après la troisième clé, et aucune boucle n&#39;apparaît. La durée médiane est la même, 2,6 s.</li><li><strong>La règle 9 est confirmée, et elle est urgente indépendamment du schéma.</strong> Aucune fonction éditoriale ne fixe aujourd&#39;hui <code>max_output_tokens</code>, et l&#39;adaptateur Ollama n&#39;envoie alors aucun <code>num_predict</code>.</li><li><strong>L&#39;assistant de filtres échoue surtout à cause d&#39;un défaut de sa consigne.</strong> Le schéma n&#39;y est pour rien. <code>build_filter_system_prompt</code> annonce le filtre de période sous son nom (<code>date</code>), alors que les paramètres attendus sont <code>date_from</code> et <code>date_to</code>. Elle ne dit pas non plus qu&#39;un filtre <code>select</code> à valeur unique n&#39;accepte qu&#39;une valeur. 13 des 15 échecs en consigne seule viennent du nom <code>date</code>. En mode schéma, la comparaison est faussée en faveur du schéma, puisque celui de la mesure portait les bons noms. Les 5 échecs restants tiennent au sens : « aujourd&#39;hui » au lieu d&#39;une date ISO, plusieurs valeurs pour un filtre unique. Aucun schéma ne les couvre ; l&#39;analyse stricte les arrête, comme prévu (règle 5).</li><li><strong>L&#39;identité de site ne gagne rien</strong> : 20/20 dans les deux modes.</li></ol><p><strong>Conséquence pour la décision.</strong> Le bénéfice existe sur le chemin par défaut, mais il est limité au brouillon : 3 échecs sur 20 évités, et surtout aucune boucle. Deux correctifs, indépendants de cette ADR et moins chers qu&#39;elle, passent avant :</p><ul><li>le plafond de sortie (règle 9) ;</li><li>la consigne de l&#39;assistant de filtres, qui doit nommer les paramètres réels et le nombre de valeurs admises.</li></ul><p>La mise en œuvre de l&#39;option (b) se limiterait ensuite au port, au catalogue, au journal et à l&#39;adaptateur Ollama, comme recommandé.</p><h2 id="décision-du-29-septembre-2026" tabindex="-1">Décision du 29 septembre 2026 <a class="header-anchor" href="#décision-du-29-septembre-2026" aria-label="Permalink to &quot;Décision du 29 septembre 2026 {#décision-du-29-septembre-2026}&quot;">​</a></h2><p>Le Product Owner accepte l&#39;ADR sur un <strong>périmètre réduit</strong>, après la mesure préalable :</p><ul><li><strong>livrés</strong> : le port (<code>ResponseSchema</code>), le catalogue (<code>structured_output</code>, garde-fou au démarrage), le Provider Manager et le journal (colonne <code>ai_jobs.structured_output</code>, migration 0044), l&#39;adaptateur <strong>Ollama</strong> seul, et le schéma des trois fonctions éditoriales ;</li><li><strong>reportés</strong> : les adaptateurs OpenAI, Anthropic et Gemini, avec leurs écarts de dialecte (règle 4) et leurs recettes payantes. Ils restent des actions ouvertes, à traiter quand une collectivité activera l&#39;un de ces fournisseurs.</li></ul><p>Deux correctifs indépendants de l&#39;ADR, révélés par la mesure, sont livrés avec elle :</p><ul><li><strong>règle 9, plafonds de sortie</strong> : chaque appel de génération des fonctions éditoriales fixe <code>max_output_tokens</code> (<code>app/ai_editorial/budgets.py</code>). Un test vérifie qu&#39;aucun <code>TextGenerationInput</code> n&#39;en est dépourvu ;</li><li><strong>consigne de l&#39;assistant de filtres</strong> : elle nomme les paramètres réels (<code>date_from</code>, <code>date_to</code>, et non <code>date</code>), et dit pour chacun le nombre et la forme des valeurs admises.</li></ul><p><strong>Recette de clôture</strong>, contre Ollama 0.34.4 et <code>llama3.1:8b</code>, sur les 20 questions de la mesure préalable : l&#39;assistant de filtres passe de <strong>5/20 à 20/20</strong> valides avec la consigne corrigée et le schéma (<code>maxItems: 1</code> sur les paramètres à valeur unique). Sur deux descriptions de site, le schéma limité au catalogue est honoré, <code>null</code> compris.</p>',65)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
